contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take parameters mirroring C.transfer: from, caddress, _tos, v.
    // The test will call c.transfer and observe if it reverts; if it does not revert it must return true.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false; // irrelevant when reverted
        }
        // General rule: if the call did not revert then it must have returned true.
        assert(reverted || ret == true);
    }
    receive() external payable {}
}

